 *   - pre-fix pattern:  only the named members are stored, trailing padding
 *                       keeps whatever dirty stack bytes were there;
 *   - post-fix pattern: memset(&map, 0, sizeof(map)) first, so all bytes
 *                       including trailing padding are zero.
 *
 * nla_put(skb, IFLA_MAP, sizeof(map), &map) copies all sizeof(map) bytes,
 * i.e. the whole 32-byte object.
 */
#include <stdio.h>
#include <string.h>
#include <stdint.h>

struct rtnl_link_ifmap {
	uint64_t mem_start;
	uint64_t mem_end;
	uint64_t base_addr;
	uint16_t irq;
	uint8_t  dma;
	uint8_t  port;
};

union slot {
	struct rtnl_link_ifmap m;
	unsigned char b[sizeof(struct rtnl_link_ifmap)];
};

/* Model the vulnerable code: memset of the whole object is absent. */
static int pre_fix_pattern(void)
{
	union slot u;
	unsigned int i;

	/* dirty kernel stack */
	memset(u.b, 0xA5, sizeof(u.b));

	u.m.mem_start = 0x1111111111111111ULL;
	u.m.mem_end   = 0x2222222222222222ULL;
	u.m.base_addr = 0x3333333333333333ULL;
	u.m.irq       = 0x4444;
	u.m.dma       = 0x55;
	u.m.port      = 0x66;

	/* nla_put(..., sizeof(map), &map) copies every byte */
	i = 0;
	while (i < sizeof(u.b)) {
		if (u.b[i] != 0xA5)
			i++;
		else
			break;
	}
	/* return 1 iff at least one dirty byte survives in the copied object */
	return i < sizeof(u.b);
}

/* Model the fixed code: full zero-initialization before member stores. */
static int post_fix_pattern(void)
{
	union slot u;
	unsigned int i;

	memset(u.b, 0xA5, sizeof(u.b));	/* dirty kernel stack */

	memset(&u.m, 0, sizeof(u.m));	/* the fix */
	u.m.mem_start = 0x1111111111111111ULL;
	u.m.mem_end   = 0x2222222222222222ULL;
	u.m.base_addr = 0x3333333333333333ULL;
	u.m.irq       = 0x4444;
	u.m.dma       = 0x55;
	u.m.port      = 0x66;

	/* return 1 iff any zeroed (padding) byte remained zero */
	i = 0;
	while (i < sizeof(u.b)) {
		if (u.b[i] == 0x00)
			i++;
		else
			break;
	}
	return i < sizeof(u.b);
}

int main(void)
{
	printf("sizeof(struct rtnl_link_ifmap) = %zu\n", sizeof(struct rtnl_link_ifmap));
	printf("named members end offset     = 28\n");
	printf("trailing padding bytes       = %zu\n", sizeof(struct rtnl_link_ifmap) - 28U);

	if (sizeof(struct rtnl_link_ifmap) != 32) {
		printf("FAIL: unexpected struct size\n");
		return 1;
	}
	if (!pre_fix_pattern()) {
		printf("FAIL: pre-fix model did not retain dirty padding\n");
		return 1;
	}
	if (!post_fix_pattern()) {
		printf("FAIL: post-fix model did not zero all bytes\n");
		return 1;
	}
	printf("PASS: pre-fix copies dirty padding; memset(&map,0,sizeof(map)) zeroes all 32 bytes\n");
	return 0;
}

